<?php
function sc_save_catalog($request,$category,$update) {
 try {
 $actor=sc_admin_guard($category?'product_category':'product',$update?'update':'create',$request);$id=$update?filter_var($request['id']??0,FILTER_VALIDATE_INT):0;if($update&&!$id)throw new RuntimeException('Invalid record.');
 $table=$category?'product_categories':'products';$existing=$update?sc_query("SELECT * FROM $table WHERE id=? AND is_deleted=0",'i',[$id])->get_result()->fetch_assoc():[];if($update&&!$existing)throw new RuntimeException('Record not found.');
 $name=trim($request[$category?'category_name':'product_name']??'');$slug=strtolower(trim($request['slug']??''));if(!$name||mb_strlen($name)>50||!preg_match('/^[a-z0-9]+(?:-[a-z0-9]+)*$/D',$slug)||strlen($slug)>50)throw new RuntimeException('Enter a name up to 50 characters and a unique URL slug using letters, numbers and hyphens.');
 if(sc_query("SELECT id FROM $table WHERE slug=? AND id<>?",'si',[$slug,$id])->get_result()->fetch_assoc())throw new RuntimeException('That URL slug already exists.');
 $remarks=trim($request['remarks']??'');if(mb_strlen($remarks)>200)throw new RuntimeException('Remarks must be 200 characters or fewer.');
 $images=$category?[$existing['category_image']??'']:(json_decode($existing['product_images']??'[]',true)?:['','','','']);
 foreach($category?['category_image']:['product_image_1','product_image_2','product_image_3','product_image_4'] as $i=>$field){if(empty($_FILES[$field]['name']))continue;$f=$_FILES[$field];if($f['error']!==UPLOAD_ERR_OK||$f['size']>1048576)throw new RuntimeException('Each image must upload successfully and be at most 1 MB.');$mime=(new finfo(FILEINFO_MIME_TYPE))->file($f['tmp_name']);if(!in_array($mime,['image/jpeg','image/png','image/webp','image/gif'],true))throw new RuntimeException('Upload a JPEG, PNG, WebP or GIF image.');$uploaded=upload_file($field);if($uploaded['status']!=='success')throw new RuntimeException($uploaded['message']);$images[$i]=$uploaded['file_name'];}
 if($category){$color=$request['color_code']??'#173e35';if(!preg_match('/^#[a-f0-9]{6}$/i',$color))throw new RuntimeException('Choose a valid category colour.');$values=[$name,$slug,$color,$images[0]??'',$remarks,$actor['id']];$types='sssssi';}
 else {
 $categoryId=filter_var($request['category_id']??0,FILTER_VALIDATE_INT);if(!$categoryId||!sc_query('SELECT id FROM product_categories WHERE id=? AND is_active=1 AND is_deleted=0','i',[$categoryId])->get_result()->fetch_assoc())throw new RuntimeException('Select an active category.');
 $type=filter_var($request['type']??-1,FILTER_VALIDATE_INT);if($type===false||$type<0||$type>3)throw new RuntimeException('Select a valid product type.');$color=trim($request['product_color']??'');if(strlen($color)>15)throw new RuntimeException('Product colour must be at most 15 characters.');
 $numbers=[];foreach(['price','discounted_price','tax1_percent','tax2_percent','igst_percent'] as $key){$v=$request[$key]??0;if(!is_numeric($v)||!is_finite((float)$v)||(float)$v<0||(float)$v>($key==='price'||$key==='discounted_price'?10000000:100))throw new RuntimeException('Enter valid non-negative prices and tax percentages.');$numbers[$key]=round((float)$v,2);}if($numbers['discounted_price']>$numbers['price'])throw new RuntimeException('Discounted price cannot exceed regular price.');
 $json=[];foreach(['details'=>['details_name','details_value'],'technology'=>['technology_name','technology_description'],'features'=>['features_name','features_value'],'pathology'=>['pathology_name','pathology_description']] as $field=>$keys){$map=[];if(isset($request[$keys[0]])&&!is_array($request[$keys[0]]))throw new RuntimeException('Invalid product specification fields.');if(isset($request[$keys[1]])&&!is_array($request[$keys[1]]))throw new RuntimeException('Invalid product specification fields.');foreach(($request[$keys[0]]??[]) as $i=>$key){$key=trim($key);if($key!=='')$map[$key]=trim($request[$keys[1]][$i]??'');}$json[$field]=json_encode($map,JSON_THROW_ON_ERROR);}
 $values=[$categoryId,$name,$slug,$color,json_encode($images),$type,$numbers['price'],$numbers['discounted_price'],$numbers['tax1_percent'],$numbers['tax2_percent'],$numbers['igst_percent'],$json['details'],$json['technology'],$json['features'],$json['pathology'],$remarks,$actor['id']];$types='issssidddddsssssi';
 }
 $db=sc_db();$db->begin_transaction();try {
 if($category){if($update)sc_query('UPDATE product_categories SET category_name=?,slug=?,color_code=?,category_image=?,remarks=?,updated_by=? WHERE id=?',$types.'i',[...$values,$id]);else sc_query('INSERT INTO product_categories (category_name,slug,color_code,category_image,remarks,updated_by,created_by) VALUES (?,?,?,?,?,?,?)',$types.'i',[...$values,$actor['id']]);}
 else {if($update)sc_query('UPDATE products SET category_id=?,product_name=?,slug=?,product_color=?,product_images=?,type=?,price=?,discounted_price=?,tax1_percent=?,tax2_percent=?,igst_percent=?,details=?,technology=?,features=?,pathology=?,remarks=?,updated_by=? WHERE id=?',$types.'i',[...$values,$id]);else sc_query('INSERT INTO products (category_id,product_name,slug,product_color,product_images,type,price,discounted_price,tax1_percent,tax2_percent,igst_percent,details,technology,features,pathology,remarks,updated_by,created_by) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)',$types.'i',[...$values,$actor['id']]);}
 if(!$update){$id=$db->insert_id;if(!$category){$last=sc_query('SELECT inventoryid FROM inventory ORDER BY inventoryid DESC LIMIT 1 FOR UPDATE')->get_result()->fetch_assoc();$serial=($last['inventoryid']??0)+1;sc_query('INSERT INTO inventory (inventoryid,site_id,product_id,quantity,created_by,updated_by) VALUES (?,?,?,0,?,?)','iiiii',[$serial,sc_stock_site(),$id,$actor['id'],$actor['id']]);$row=['id'=>$db->insert_id,'product_id'=>$id,'site_id'=>sc_stock_site()];sc_stock_log($row,0,0,$actor['id'],'Initial inventory entry');}}
 $db->commit();return ['status'=>'success','message'=>$category?'Product category saved.':'Product saved. Add stock through Inventory before selling.','id'=>$id];
 }catch(Throwable $e){$db->rollback();throw $e;}
 }catch(mysqli_sql_exception $e){error_log($e->getMessage());return ['status'=>'failed','message'=>'Unable to save. Check that the URL slug is unique and try again.'];}catch(Throwable $e){return ['status'=>'failed','message'=>$e instanceof RuntimeException?$e->getMessage():'Please check the submitted fields.'];}
}
